任务：创建前端API层

请创建以下三个文件，严格遵循现有 `src/api/request.js` 和 `src/api/user.js` 的写法模式：

### 1. src/api/feedback.js
```js
// 反馈工单接口封装
import { request } from './request.js'

// 创建反馈
export function createFeedback(payload) {
  return request('/v1/reports', {
    method: 'POST',
    auth: true,
    body: {
      type: payload.type,
      category: payload.category,
      content: payload.content,
      media_ids: payload.mediaIds,
      client_info_consent: payload.clientInfoConsent
    }
  })
}

// 获取反馈列表
export function listFeedback(params) {
  const qs = new URLSearchParams()
  if (params.page != null) qs.set('page', String(params.page))
  if (params.pageSize != null) qs.set('pageSize', String(params.pageSize))
  if (params.status) qs.set('status', params.status)
  if (params.type) qs.set('type', params.type)
  if (params.mine != null) qs.set('mine', String(params.mine))
  if (params.reporterUserId) qs.set('reporterUserId', params.reporterUserId)
  if (params.q) qs.set('q', params.q)
  if (params.sortBy) qs.set('sortBy', params.sortBy)
  if (params.sortOrder) qs.set('sortOrder', params.sortOrder)
  const query = qs.toString()
  return request(`/v1/reports${query ? '?' + query : ''}`, { auth: true })
}

// 获取单个反馈详情
export function getFeedback(id) {
  return request(`/v1/reports/${encodeURIComponent(id)}`, { auth: true })
}

// 追加消息
export function appendFeedbackMessage(id, body) {
  return request(`/v1/reports/${encodeURIComponent(id)}/messages`, {
    method: 'POST',
    auth: true,
    body: {
      content: body.content,
      media_ids: body.mediaIds
    }
  })
}

// 更新状态
export function updateFeedbackStatus(id, status) {
  return request(`/v1/reports/${encodeURIComponent(id)}/status`, {
    method: 'PATCH',
    auth: true,
    body: { status }
  })
}
```

### 2. src/api/media.js
```js
// 媒体上传接口封装
import { request } from './request.js'

// 上传图片
export function uploadMedia(file) {
  const formData = new FormData()
  formData.append('file', file)
  return request('/v1/media/upload', {
    method: 'POST',
    auth: true,
    multipart: true,
    body: formData
  })
}
```

### 3. src/api/notifications.js
```js
// 站内通知接口封装
import { request } from './request.js'

// 获取通知列表
export function listNotifications(params) {
  const qs = new URLSearchParams()
  if (params.page != null) qs.set('page', String(params.page))
  if (params.pageSize != null) qs.set('pageSize', String(params.pageSize))
  if (params.unreadOnly != null) qs.set('unreadOnly', String(params.unreadOnly))
  const query = qs.toString()
  return request(`/v1/notifications${query ? '?' + query : ''}`, { auth: true })
}

// 获取未读通知数
export function getUnreadNotificationCount() {
  return request('/v1/notifications/unread-count', { auth: true })
}

// 标记单条通知已读
export function markNotificationRead(id) {
  return request(`/v1/notifications/${encodeURIComponent(id)}/read`, {
    method: 'PATCH',
    auth: true,
    body: {}
  })
}

// 标记全部已读
export function markAllNotificationsRead() {
  return request('/v1/notifications/read-all', {
    method: 'PATCH',
    auth: true,
    body: {}
  })
}
```

请创建这三个文件，确保代码风格与现有项目一致（使用 `function` 声明、`camelCase` 参数名转 `snake_case` 请求体字段等）。
